const c=s=>s._context?.civ||s.world?.settlements[0],known=(s,id)=>c(s)?.discoveries.includes(id),bal=(s,k)=>Object.hasOwn(s.industry,k)?s.industry[k]:s[k];
export const VEHICLES={cart:{durability:180,speed:180,capacity:32,cost:{wood:48,metal:8},requires:'wheelcraft',facility:'mechanicalLab'},motor:{durability:400,speed:300,capacity:60,cost:{metal:20,alloy:12,energy:20},requires:'electricity',facility:'mechanicalLab'},biotic:{durability:240,speed:220,capacity:40,cost:{food:40,wood:20},requires:'bioMobility',facility:'bioticGarden'}};
export const WEAPONS={stone:{durability:60,power:.7,cost:{wood:6,stone:3},requires:'weaponry'},metal:{durability:120,power:1.4,cost:{metal:10,fuel:4},requires:'metallurgy'},ballistic:{durability:180,power:2.5,cost:{alloy:12,energy:10},requires:'ballistics'}};
const can=(s,cost)=>Object.entries(cost).every(([k,v])=>bal(s,k)>=v),pay=(s,cost)=>{for(const [k,v]of Object.entries(cost))if(Object.hasOwn(s.industry,k))s.industry[k]-=v;else s[k]-=v;};
function pruneEquipment(s,category,limit){while(s[category].length>limit){const index=s[category].findIndex(item=>item.condition<=0&&(category==='weapons'?!s.agents.some(a=>a.alive&&a.equipment.weapon===item.id):!s.agents.some(a=>a.alive&&a.journey?.vehicle===item.id)));if(index<0)break;s[category].splice(index,1);}}
export function equipmentActions(s){const list=[];if(s.buildings.arsenal&&known(s,'weaponry')&&s.weapons.filter(w=>w.condition>0).length<Math.min(128,s.agents.filter(a=>a.alive).length)&&Object.values(WEAPONS).some(w=>known(s,w.requires)&&can(s,w.cost)))list.push('forgeWeapon');if(s.vehicleProject||s.vehicles.filter(v=>v.condition>0).length<Math.min(32,Math.ceil(s.agents.filter(a=>a.alive).length/6))&&Object.values(VEHICLES).some(v=>known(s,v.requires)&&s.buildings[v.facility]&&can(s,v.cost)))list.push('makeVehicle');return list;}
export function equipmentWork(s,a,key,scale,log){if(key==='forgeWeapon'){if(!equipmentActions(s).includes(key))return {reward:-1,energy:1};const [type,spec]=Object.entries(WEAPONS).reverse().find(([,w])=>known(s,w.requires)&&can(s,w.cost));pay(s,spec.cost);s.weapons.push({id:s.nextWeaponId++,type,condition:100,uses:0,owner:null});pruneEquipment(s,'weapons',512);equipWeapon(s,a);s._turn?.allocations.push({purpose:'Senjata '+type,inputs:{...spec.cost}});return {reward:3,energy:8,target:'Senjata '+type};}if(!s.vehicleProject){const option=Object.entries(VEHICLES).reverse().find(([,v])=>known(s,v.requires)&&s.buildings[v.facility]&&can(s,v.cost));if(!option)return {reward:-1,energy:1};const [type,spec]=option;pay(s,spec.cost);s.vehicleProject={type,progress:0,required:40};s._turn?.allocations.push({purpose:'Kendaraan '+type,inputs:{...spec.cost}});}s.vehicleProject.progress=Math.min(40,s.vehicleProject.progress+2*scale);if(s.vehicleProject.progress>=40){const type=s.vehicleProject.type,v=VEHICLES[type];s.vehicles.push({id:s.nextVehicleId++,type,speed:v.speed,capacity:v.capacity,condition:100,uses:0});pruneEquipment(s,'vehicles',256);s.vehicleProject=null;log(s,'Kendaraan '+type+' selesai; dapat mempercepat perjalanan dan membawa muatan lebih banyak.');}return {reward:3,energy:7};}
export function equipWeapon(s,a){
 if(!a||!a.alive)return null;
 const current=s.weapons.find(w=>w.id===a.equipment.weapon&&w.owner===a.id&&w.condition>0);
 const candidate=s.weapons.filter(w=>w.condition>0&&(w.owner===null||w.owner===undefined||w.owner===a.id)&&!s.agents.some(b=>b.alive&&b.id!==a.id&&b.equipment.weapon===w.id)).sort((x,y)=>WEAPONS[y.type].power-WEAPONS[x.type].power)[0];
 if(current&&(!candidate||WEAPONS[current.type].power>=WEAPONS[candidate.type].power))return current;
 if(current)current.owner=null;
 if(!candidate){delete a.equipment.weapon;return null;}candidate.owner=a.id;a.equipment.weapon=candidate.id;return candidate;
}
export function weaponPower(s,a){const w=equipWeapon(s,a);if(!w)return 0;s._turn.armed??=new Set();if(s._turn.armed.has(w.id))return 0;s._turn.armed.add(w.id);w.uses++;w.condition=Math.max(0,w.condition-100/WEAPONS[w.type].durability);if(!w.condition){delete a.equipment.weapon;w.owner=null;}return WEAPONS[w.type].power;}
